from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            L = len(digits)

            @lru_cache(maxsize=None)
            def dp(pos: int, started: bool, sumd: int, prod: int, tight: bool) -> int:
                if pos == L:
                    return 1 if started and sumd > 0 and prod % sumd == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    ntight = tight and (d == limit)

                    if not started and d == 0:
                        # Leading zero: does not affect sum or product.
                        total += dp(pos + 1, False, 0, 1, ntight)
                    else:
                        # A real zero digit makes the whole product zero.
                        total += dp(pos + 1, True, sumd + d, prod * d, ntight)

                return total

            return dp(0, False, 0, 1, True)

        return count_upto(r) - count_upto(l - 1)

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # powers of 4 up to 1e9
        powers = []
        p = 1
        while p <= 10**9:
            powers.append(p)
            p *= 4

        # d(x) = number of powers 1,4,16,... that are <= x  (for x >= 1)
        # F(n) = sum_{x=1}^{n} d(x) = sum_{j>=1} max(0, n - 4^{j-1} + 1)
        def F(n: int) -> int:
            if n <= 0:
                return 0
            s = 0
            for pw in powers:
                if pw > n:
                    break
                s += n - pw + 1
            return s

        def d(x: int) -> int:
            # smallest k with 4^k > x  -> equals count of powers <= x
            c = 0
            for pw in powers:
                if pw > x:
                    break
                c += 1
            return c

        total = 0
        for l, r in queries:
            S = F(r) - F(l - 1)
            # min ops = max(max single-element cost, ceil(total cost / 2))
            total += max(d(r), (S + 1) // 2)
        return total

