from itertools import product


class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(L: int) -> bool:
            if L == 1:
                # Only alternating strings have all runs of length 1.
                # The two patterns are complements, so mismatches sum to n.
                m1 = 0
                for i, ch in enumerate(s):
                    a = '0' if (i & 1) == 0 else '1'
                    if ch != a:
                        m1 += 1
                return min(m1, n - m1) <= numOps

            # For L >= 2, each maximal run of length `len` costs
            # exactly len // (L+1) interior flips, and runs are independent.
            total = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                total += (j - i) // (L + 1)
                if total > numOps:
                    return False
                i = j
            return True

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo


def brute_all(s):
    """Return best[k] = min possible longest-run using at most k flips."""
    n = len(s)
    INF = n + 1
    exact = [INF] * (n + 1)
    for mask in range(1 << n):
        f = bin(mask).count('1')
        chars = list(s)
        for i in range(n):
            if (mask >> i) & 1:
                chars[i] = '1' if chars[i] == '0' else '0'
        mr = 1
        cur = 1
        for i in range(1, n):
            if chars[i] == chars[i - 1]:
                cur += 1
            else:
                cur = 1
            if cur > mr:
                mr = cur
        if mr < exact[f]:
            exact[f] = mr
    res = [INF] * (n + 1)
    best = INF
    for k in range(n + 1):
        if exact[k] < best:
            best = exact[k]
        res[k] = best
    return res


