    solve()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # prefix function of str2
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # KMP failure links over states 0..m
        fail = [0] * (m + 1)
        for s in range(1, m + 1):
            fail[s] = pi[s - 1]

        # delta[s][c] = next state
        delta = [[0] * 26 for _ in range(m + 1)]
        for s in range(m + 1):
            row = delta[s]
            if s < m:
                nxt = s + 1
                mc = ord(str2[s]) - 97
                if s == 0:
                    for c in range(26):
                        row[c] = nxt if c == mc else 0
                else:
                    fr = delta[fail[s]]
                    for c in range(26):
                        row[c] = nxt if c == mc else fr[c]
            else:
                fr = delta[fail[s]]
                for c in range(26):
                    row[c] = fr[c]

        # back[t] = bitmask of states s with some c giving delta[s][c] == t
        back = [0] * (m + 1)
        for s in range(m + 1):
            bs = 1 << s
            ds = delta[s]
            for c in range(26):
                back[ds[c]] |= bs

        nstates = m + 1
        nchunks = (nstates + 7) // 8
        tables = []
        for k in range(nchunks):
            tbl = [0] * 256
            base = 8 * k
            for byte in range(1, 256):
                low = byte & (-byte)
                j = low.bit_length() - 1
                prev = tbl[byte ^ low]
                t = base + j
                tbl[byte] = (prev | back[t]) if t <= m else prev
            tables.append(tbl)

        def preimage(A):
            res = 0
            k = 0
            while A:
                res |= tables[k][A & 255]
                A >>= 8
                k += 1
            return res

        full = (1 << nstates) - 1
        F = [0] * (L + 1)
        F[L] = full
        for p in range(L - 1, -1, -1):
            A = F[p + 1]
            if p >= m - 1:
                i = p - m + 1
                if str1[i] == 'T':
                    A &= (1 << m)
                else:
                    A &= ~(1 << m)
            F[p] = preimage(A)

        if not (F[0] & 1):
            return ""

        res = []
        state = 0
        for p in range(L):
            Fnext = F[p + 1]
            ch = str1[p - m + 1] if p >= m - 1 else None
            for c in range(26):
                t = delta[state][c]
                if ch == 'T':
                    if t != m:
                        continue
                elif ch == 'F':
                    if t == m:
                        continue
                if (Fnext >> t) & 1:
                    res.append(chr(97 + c))
                    state = t
                    break
            else:
                return ""
        return ''.join(res)


