from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        S = sum(nums)
        off = S
        target = k + off
        if target < 0 or target > 2 * S:
            return -1

        # Zero-product DP: states (hasZero, parity) -> bitset of alternating sums
        zero = {(False, 0): 1 << off}
        for v in nums:
            items = list(zero.items())
            for (hz, par), bits in items:
                if bits == 0:
                    continue
                nhz = hz or (v == 0)
                if par == 0:
                    npar = 1
                    shifted = bits << v
                else:
                    npar = 0
                    shifted = bits >> v
                key = (nhz, npar)
                zero[key] = zero.get(key, 0) | shifted

        zero_reach = False
        if (True, 0) in zero and ((zero[(True, 0)] >> target) & 1):
            zero_reach = True
        elif (True, 1) in zero and ((zero[(True, 1)] >> target) & 1):
            zero_reach = True

        # Positive-product DP: even[p], odd[p] are bitsets of alternating sums
        even = [0] * (limit + 1)
        odd = [0] * (limit + 1)
        for v in nums:
            if v == 0:
                continue
            # snapshot before using v, so v is used at most once
            items = [(p, even[p], odd[p]) for p in range(1, limit + 1) if even[p] or odd[p]]
            # start a new subsequence with v
            if v <= limit:
                odd[v] |= 1 << (v + off)
            # append v to existing subsequences
            for p, be, bo in items:
                np = p * v
                if np > limit:
                    continue
                if be:
                    odd[np] |= be << v
                if bo:
                    even[np] |= bo >> v

        for p in range(limit, 0, -1):
            if ((even[p] | odd[p]) >> target) & 1:
                return p

        if zero_reach:
            return 0
        return -1

import sys
from collections import deque

def main():
    sys.setrecursionlimit(10000)
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it)); M = int(next(it)); K = int(next(it))
    edges = []
    for _ in range(M):
        u = int(next(it)); v = int(next(it))
        edges.append((u, v))

    INF = 1 << 30

    def feasible(L):
        # Is min number of edges to select (so every 1->N path has >= L of them) <= K ?
        if L <= 0:
            return True
        num = N * L
        S = num
        T = num + 1
        n = num + 2
        graph = [[] for _ in range(n)]

        def add(fr, to, cap):
            graph[fr].append([to, cap, len(graph[to])])
            graph[to].append([fr, 0, len(graph[fr]) - 1])

        def aid(v, t):        # v in 1..N, t in 1..L
            return (v - 1) * L + (t - 1)

        # Node A(v,t) on source side <=> d(v) >= t.
        # Monotonicity: d(v)>=t implies d(v)>=t-1
        for v in range(1, N + 1):
            base = (v - 1) * L
            for t in range(2, L + 1):
                add(base + t - 1, base + t - 2, INF)
        # d(1) = 0  -> A(1,t) forced to sink side
        for t in range(1, L + 1):
            add(aid(1, t), T, INF)
        # d(N) = L  -> A(N,t) forced to source side
        for t in range(1, L + 1):
            add(S, aid(N, t), INF)
        # Original edges u->v
        for (u, v) in edges:
            bu = (u - 1) * L
            bv = (v - 1) * L
            # cost: A(v,t) source and A(u,t) sink  => tight edge (d(v)=d(u)+1)
            for t in range(1, L + 1):
                add(bv + t - 1, bu + t - 1, 1)
            # constraint d(v) <= d(u)+1 : A(v,t) source => A(u,t-1) source
            for t in range(2, L + 1):
                add(bv + t - 1, bu + t - 2, INF)

        level = [-1] * n
        it_arr = [0] * n

        def bfs():
            for i in range(n):
                level[i] = -1
            level[S] = 0
            q = deque([S])
            while q:
                x = q.popleft()
                for to, cap, rev in graph[x]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[x] + 1
                        q.append(to)
            return level[T] >= 0

        def dfs(x, f):
            if x == T:
                return f
            while it_arr[x] < len(graph[x]):
                e = graph[x][it_arr[x]]
                to, cap, rev = e
                if cap > 0 and level[x] < level[to]:
                    d = dfs(to, f if f < cap else cap)
                    if d > 0:
                        e[1] -= d
                        graph[to][rev][1] += d
                        return d
                it_arr[x] += 1
            return 0

        flow = 0
        while bfs():
            for i in range(n):
                it_arr[i] = 0
            while True:
                f = dfs(S, INF)
                if f == 0:
                    break
                flow += f
                if flow > K:
                    break
            if flow > K:
                break
        return flow <= K

    ans = 0
    for L in range(N - 1, 0, -1):
        if feasible(L):
            ans = L
            break
    print(ans)

main()

import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    grid = data[1:1+N]

    outmask = [[0]*26 for _ in range(N)]
    inlist = [[[] for _ in range(N)] for _ in range(26)]
    vchars = [[] for _ in range(N)]

    for u in range(N):
        row = grid[u]
        for v, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                outmask[u][c] |= (1 << v)
                inlist[c][v].append(u)
    for u in range(N):
        for c in range(26):
            if outmask[u][c]:
                vchars[u].append(c)

    dist = [[-1]*N for _ in range(N)]
    unsettled = [(1 << N) - 1] * N
    q = deque()

    # level 0: empty palindromes
    for i in range(N):
        dist[i][i] = 0
        unsettled[i] &= ~(1 << i)
        q.append((i, i))

    # level 1: single edges (u != v). Self-loops are skipped as base states,
    # but remain available as edges in extensions.
    for u in range(N):
        row = grid[u]
        for v, ch in enumerate(row):
            if ch != '-' and u != v:
                if dist[u][v] == -1:
                    dist[u][v] = 1
                    unsettled[u] &= ~(1 << v)
                    q.append((u, v))

    while q:
        x, y = q.popleft()
        d = dist[x][y]
        nd = d + 2
        newacc = [0] * N
        for c in vchars[y]:
            mask = outmask[y][c]
            for a in inlist[c][x]:
                newacc[a] |= mask
        for a in range(N):
            mask = newacc[a]
            if mask:
                newbits = mask & unsettled[a]
                if newbits:
                    m = newbits
                    while m:
                        lsb = m & -m
                        b = lsb.bit_length() - 1
                        dist[a][b] = nd
                        unsettled[a] &= ~lsb
                        q.append((a, b))
                        m ^= lsb

    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(str(dist[i][j]) for j in range(N)))
    sys.stdout.write('\n'.join(out_lines))

