import sys

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    H = int(data[pos]); W = int(data[pos + 1]); pos += 2
    N = H * W
    F = [0] * N
    for i in range(N):
        F[i] = int(data[pos]); pos += 1
    Q = int(data[pos]); pos += 1

    lo_arr = [0] * Q
    hi_arr = [0] * Q
    m = [0] * Q
    qs = [None] * N

    for qid in range(Q):
        A = int(data[pos]); B = int(data[pos + 1]); Y = int(data[pos + 2])
        C = int(data[pos + 3]); D = int(data[pos + 4]); Z = int(data[pos + 5])
        pos += 6
        u = (A - 1) * W + (B - 1)
        v = (C - 1) * W + (D - 1)
        if Y < Z:
            lo_arr[qid] = Y; hi_arr[qid] = Z
        else:
            lo_arr[qid] = Z; hi_arr[qid] = Y
        if u == v:
            m[qid] = F[u]
        else:
            if qs[u] is None:
                qs[u] = {qid}
            else:
                qs[u].add(qid)
            if qs[v] is None:
                qs[v] = {qid}
            else:
                qs[v].add(qid)
    del data

    parent = list(range(N))
    size = [1] * N

    def find(x, parent=parent):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge_roots(ru, rv, cap, parent=parent, size=size, qs=qs, m=m):
        if size[ru] < size[rv]:
            ru, rv = rv, ru
        A = qs[ru]; B = qs[rv]
        if B is not None:
            if A is None:
                qs[ru] = B
            else:
                if len(A) < len(B):
                    A, B = B, A
                for qid in B:
                    if qid in A:
                        m[qid] = cap
                        A.remove(qid)
                    else:
                        A.add(qid)
                qs[ru] = A if A else None
        qs[rv] = None
        parent[rv] = ru
        size[ru] += size[rv]
        return ru

    order = sorted(range(N), key=F.__getitem__, reverse=True)
    added = bytearray(N)

    for u in order:
        added[u] = 1
        cap = F[u]
        ru = find(u)
        j = u % W
        if j and added[u - 1]:
            rv = find(u - 1)
            if rv != ru:
                ru = merge_roots(ru, rv, cap)
        if j < W - 1 and added[u + 1]:
            rv = find(u + 1)
            if rv != ru:
                ru = merge_roots(ru, rv, cap)
        if u >= W and added[u - W]:
            rv = find(u - W)
            if rv != ru:
                ru = merge_roots(ru, rv, cap)
        if u + W < N and added[u + W]:
            rv = find(u + W)
            if rv != ru:
                ru = merge_roots(ru, rv, cap)

    out = []
    for qid in range(Q):
        lo = lo_arr[qid]; hi = hi_arr[qid]; mm = m[qid]
        ans = hi - lo
        if lo > mm:
            ans += 2 * (lo - mm)
        out.append(str(ans))
    sys.stdout.write('\n'.join(out) + '\n')

main()

import sys
import numpy as np


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])
    D = N * (N - 1) // 2
    L = D + 1
    half = N // 2

    # Binomial coefficients mod P for n <= N
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for n in range(N + 1):
        C[n][0] = 1 % P
        for k in range(1, n + 1):
            val = C[n - 1][k - 1]
            if k <= n - 1:
                val += C[n - 1][k]
            C[n][k] = val % P

    # bs[p, s, t] = ((1+t)^p - 1)^s * (1+t)^{C(s,2)} mod P
    bs = np.zeros((N + 1, N + 1, L), dtype=np.int64)
    for t in range(L):
        v = (1 + t) % P
        vp = [1] * (N + 1)
        for i in range(1, N + 1):
            vp[i] = vp[i - 1] * v % P
        for p in range(1, N + 1):
            term = (vp[p] - 1) % P
            cur = 1
            f2 = 1
            row = bs[p]
            for s in range(1, N + 1):
                cur = cur * term % P
                if s >= 2:
                    f2 = f2 * vp[s - 1] % P
                row[s, t] = cur * f2 % P

    # state: (used, odd_sum, prev_layer_size, last_layer_parity)
    dp = {(1, 0, 1, 0): np.ones(L, dtype=np.int64)}

    for u in range(1, N):
        keys = [k for k in dp if k[0] == u]
        if not keys:
            continue
        remaining = N - u
        cp = C[remaining]
        W = {}
        for p in range(1, N + 1):
            row = bs[p]
            Wp = [None] * (remaining + 1)
            for s in range(1, remaining + 1):
                Wp[s] = row[s] * cp[s] % P
            W[p] = Wp
        newadds = {}
        for key in keys:
            o = key[1]
            p = key[2]
            par = key[3]
            src = dp.pop(key)
            src %= P
            Wp = W[p]
            if par == 0:
                # next layer is odd-indexed: its vertices count toward o
                smax = half - o
                if smax > remaining:
                    smax = remaining
                for s in range(1, smax + 1):
                    tmp = src * Wp[s] % P
                    nk = (u + s, o + s, s, 1)
                    old = newadds.get(nk)
                    if old is None:
                        newadds[nk] = tmp
                    else:
                        old += tmp
            else:
                # next layer is even-indexed
                smax = half - (u - o)
                if smax > remaining:
                    smax = remaining
                for s in range(1, smax + 1):
                    tmp = src * Wp[s] % P
                    nk = (u + s, o, s, 0)
                    old = newadds.get(nk)
                    if old is None:
                        newadds[nk] = tmp
                    else:
                        old += tmp
        for k, v in newadds.items():
            old = dp.get(k)
            if old is None:
                dp[k] = v
            else:
                old += v

    total = np.zeros(L, dtype=np.int64)
    for (u, o, p, par), arr in dp.items():
        if u == N and o == half:
            total += arr % P
    total %= P
    y = [int(x) for x in total.tolist()]

    # Lagrange interpolation of the degree <= D polynomial through (t, y[t])
    Mp = [1]
    for t in range(L):
        new = [0] * (len(Mp) + 1)
        for i, c in enumerate(Mp):
            if c:
                new[i + 1] = (new[i + 1] + c) % P
                new[i] = (new[i] - c * t) % P
        Mp = new

    res = [0] * L
    for t in range(L):
        mp = 1
        for j in range(L):
            if j != t:
                mp = mp * (t - j) % P
        ct = y[t] * pow(mp, P - 2, P) % P
        if ct == 0:
            continue
        q = [0] * L
        q[L - 1] = Mp[L]
        for i in range(L - 1, 0, -1):
            q[i - 1] = (Mp[i] + t * q[i]) % P
        for i in range(L):
            res[i] = (res[i] + ct * q[i]) % P

    out = [str(res[M] % P) for M in range(N - 1, D + 1)]
    sys.stdout.write(' '.join(out) + '\n')


main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0]); M = int(data[1]); A = int(data[2]); B = int(data[3])

    # Merge touching/overlapping bad intervals into maximal bad blocks.
    merged = []
    idx = 4
    for _ in range(M):
        L = int(data[idx]); R = int(data[idx + 1]); idx += 2
        if merged and L <= merged[-1][1] + 1:
            if R > merged[-1][1]:
                merged[-1] = (merged[-1][0], R)
        else:
            merged.append((L, R))

    # Case A == B: the path is forced.
    if A == B:
        if (N - 1) % A != 0:
            sys.stdout.write("No\n"); return
        K = (N - 1) // A
        for L, R in merged:
            klo = (L - 1 + A - 1) // A   # smallest k with 1+k*A >= L
            khi = (R - 1) // A           # largest  k with 1+k*A <= R
            if klo <= khi:               # some forced square is bad
                sys.stdout.write("No\n"); return
        sys.stdout.write("Yes\n"); return

    # Case A < B: a maximal bad block of length >= B cannot be crossed.
    for L, R in merged:
        if R - L + 1 >= B:
            sys.stdout.write("No\n"); return

    full = (1 << B) - 1
    band = ((1 << (B - A + 1)) - 1) << (A - 1)   # bits [A-1, B-1]
    T = A * A + B + 5                            # safe saturation bound

    mask = 1   # bit 0 = current square reachable
    x = 1
    ok = True

    for L, R in merged:
        g = L - 1 - x            # all-good squares x+1 .. L-1
        if g > 0:
            if mask == 0:
                ok = False; break
            if g >= T:
                mask = full      # all-ones is a fixed point
            else:
                for _ in range(g):
                    if mask == full:
                        break
                    if mask & band:
                        mask = ((mask << 1) | 1) & full
                    else:
                        mask = (mask << 1) & full
            x = L - 1
        b = R - L + 1            # bad block: new bits forced to 0
        mask = (mask << b) & full
        if mask == 0:
            ok = False; break
        x = R

    if ok:
        g = N - x
        if g > 0:
            if mask == 0:
                ok = False
            elif g >= T:
                mask = full
            else:
                for _ in range(g):
                    if mask == full:
                        break
                    if mask & band:
                        mask = ((mask << 1) | 1) & full
                    else:
                        mask = (mask << 1) & full
        if ok:
            ok = (mask & 1) == 1

    sys.stdout.write("Yes\n" if ok else "No\n")

